import React, { useState, useEffect } from "react";
import axios from "axios";

function OrderPage() {
  const [menu, setMenu] = useState([]);
  const [selectedItems, setSelectedItems] = useState([]);
  const [tableNumber, setTableNumber] = useState("");
  const [orders, setOrders] = useState([]);

  // Load menu + orders
  useEffect(() => {
    axios.get("http://localhost:5000/api/menu")
      .then(res => setMenu(res.data))
      .catch(err => console.error("Error fetching menu:", err));

    axios.get("http://localhost:5000/api/orders")
      .then(res => setOrders(res.data))
      .catch(err => console.error("Error fetching orders:", err));
  }, []);

  // Toggle item selection
  const toggleItem = (item) => {
    setSelectedItems(prev =>
      prev.find(i => i.id === item.id)
        ? prev.filter(i => i.id !== item.id)
        : [...prev, { ...item, quantity: 1 }]
    );
  };

  // Update quantity
  const updateQuantity = (id, qty) => {
    setSelectedItems(prev =>
      prev.map(i => i.id === id ? { ...i, quantity: qty } : i)
    );
  };

  // Place order
  const placeOrder = () => {
    if (!tableNumber || selectedItems.length === 0) {
      alert("Please enter table number and select items");
      return;
    }
    axios.post("http://localhost:5000/api/orders", {
      table_number: parseInt(tableNumber, 10),
      items: selectedItems.map(i => ({ menu_id: i.id, quantity: i.quantity }))
    })
    .then(res => {
      alert(`Order placed! ID: ${res.data.orderId}`);
      setSelectedItems([]);
      refreshOrders();
    })
    .catch(err => alert("Error placing order: " + err.message));
  };

  // Pay bill
  const payBill = (orderId) => {
    axios.post(`http://localhost:5000/api/orders/${orderId}/pay`)
      .then(res => {
        alert(`Bill for order ${orderId} paid! Total: ₹${res.data.total}`);
        refreshOrders();
      })
      .catch(err => {
        const message = err.response?.data?.error || err.message;
        alert("Error paying bill: " + message);
      });
  };

  // Refresh orders
  const refreshOrders = () => {
    axios.get("http://localhost:5000/api/orders")
      .then(r => setOrders(r.data));
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Place Order</h2>
      <input
        type="number"
        placeholder="Table Number"
        value={tableNumber}
        onChange={e => setTableNumber(e.target.value)}
        style={{ marginBottom: "10px" }}
      />

      <ul style={{ listStyle: "none", padding: 0 }}>
        {menu.map(item => (
          <li key={item.id} style={{ marginBottom: "10px" }}>
            <label>
              <input
                type="checkbox"
                onChange={() => toggleItem(item)}
                checked={selectedItems.some(i => i.id === item.id)}
              />
              {item.name} — ₹{item.price}
            </label>
            {selectedItems.some(i => i.id === item.id) && (
              <input
                type="number"
                min="1"
                value={selectedItems.find(i => i.id === item.id)?.quantity || 1}
                onChange={e => updateQuantity(item.id, parseInt(e.target.value))}
                style={{ marginLeft: "10px", width: "60px" }}
              />
            )}
          </li>
        ))}
      </ul>

      <button onClick={placeOrder} style={{ marginTop: "10px" }}>
        Submit Order
      </button>

      <h2 style={{ marginTop: "30px" }}>Existing Orders</h2>
      {orders.length === 0 ? (
        <p>No orders yet.</p>
      ) : (
        <ul>
          {orders.map(order => (
            <li key={order.id} style={{ marginBottom: "10px" }}>
              Table {order.table_number} — Status: {order.status} — Chef: {order.chef_id || "Unassigned"}
              {order.status !== "Paid" && (
                <button
                  style={{ marginLeft: "10px" }}
                  onClick={() => payBill(order.id)}
                >
                  Pay Bill
                </button>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default OrderPage;
